'use strict';
// Screen projections only: no persistence or event/reward mutation in this module.
window.CompanyScreens=(()=>{
const $=id=>document.getElementById(id),D=CompanyDomain;
const equipment=[{level:1,name:'机と椅子',icon:'desk'},{level:2,name:'観葉植物',icon:'plant'},{level:3,name:'PCと書棚',icon:'monitor'}];
const awards=[{name:'はじめの一仕事',test:s=>s.completed.length>=1,note:'1案件を完遂'},{name:'頼れる社長',test:s=>s.completed.length>=5,note:'5案件を完遂'},{name:'こつこつ経営賞',test:s=>s.completed.length>=10,note:'10案件を完遂'},{name:'本日の立役者',test:s=>{const days={};s.completed.forEach(t=>{if(!D.validTimestamp(t.completedAt))return;const d=D.localDate(new Date(t.completedAt));days[d]=(days[d]||0)+1;});return s.today>=3||Object.values(days).some(n=>n>=3);},note:'1日に3案件を完遂'}];
function taskGroup(deadline){if(!D.parseDate(deadline))return 'none';if(deadline<=D.day())return 'today';if(deadline<=D.localDate(D.addDays(new Date(),3)))return 'near';return 'future';}
function prepareJobs(state){document.querySelectorAll('#tasks>.empty').forEach(e=>e.remove());state.tasks.sort((a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999'));for(const group of ['today','near','future','none']){$('tasks-'+group).replaceChildren();document.querySelector('[data-group="'+group+'"]').hidden=!state.tasks.some(t=>taskGroup(t.deadline)===group);}}
function renderHome(s,g){const today=D.day(),yesterday=D.localDate(D.addDays(new Date(),-1));const old=s.completed.filter(t=>D.validTimestamp(t.completedAt)&&D.localDate(new Date(t.completedAt))===yesterday).length;const yesterdayCount=s.previousDay?.day===yesterday?Math.max(old,s.previousDay.count||0):old;const next=g.level===1?'観葉植物':g.level===2?'PCと書棚':'次の会社成長';const left=(g.cost-g.remaining).toLocaleString();const templates=[`${s.companyName}、本日も営業中。無理のない経営をお願いします。${next}まで、あと${left} EXPです。`, `社長の小さな一歩を、総務部は見ています。${next}の導入予算まで、あと${left} EXP。`, `本日の社内目標は、ひとつ「できた」を増やすこと。歯磨きも、立派な業務です。`];let seed=0;for(const c of today)seed=seed*31+c.charCodeAt(0);$('daily-report').textContent=s.today>0?`本日は${s.today}案件を完遂、${s.sales.toLocaleString()} EXPを計上。社長の活躍に、経理部もにっこり。${next}まであと${left} EXPです。`:yesterdayCount>0?`昨日は${yesterdayCount}案件を完遂。${s.companyName}の成長に、全社員（社長）が拍手。${next}まであと${left} EXPです。`:templates[Math.abs(seed)%templates.length];$('report-date').textContent=new Date().toLocaleDateString('ja-JP',{month:'numeric',day:'numeric'});const due=s.tasks.filter(t=>D.parseDate(t.deadline)&&t.deadline<=D.quickDeadline('tomorrow'));$('deadline-reminder').hidden=!s.reminders||!due.length;$('deadline-reminder').textContent=`営業部より：今日・明日までの案件が${due.length}件あります。案件台帳をご確認ください。`;}
function renderRecords(s,g){$('record-level').textContent='Lv.'+g.level;const list=$('equipment-list');list.replaceChildren();for(const e of equipment){const card=document.createElement('div');card.className='equipment'+(g.level<e.level?' locked':'');card.innerHTML=CompanyIcons.svg(e.icon);const name=document.createElement('b');name.textContent=e.name;const note=document.createElement('small');note.textContent=g.level>=e.level?'導入済み':'Lv.'+e.level+'で導入';card.append(name,note);list.append(card);}$('awards-list').replaceChildren();for(const award of awards){const achieved=award.test(s),card=document.createElement('div');card.className='award-card'+(!achieved?' locked':'');card.innerHTML=CompanyIcons.svg('award');const name=document.createElement('b');name.textContent=award.name;const note=document.createElement('small');note.textContent=achieved?'表彰済み':award.note;card.append(name,note);$('awards-list').append(card);}$('growth-list').replaceChildren();for(const log of s.growthLog){const p=document.createElement('p');p.className='growth-record';p.textContent=new Date(log.occurredAt).toLocaleDateString('ja-JP')+' ／ 会社成長 Lv.'+log.from+' → Lv.'+log.to;$('growth-list').append(p);}}
function renderAdmin(s){$('admin-company').textContent=s.companyName;$('effects-setting').value=s.effects;$('reminders-setting').checked=s.reminders;}
return{taskGroup,prepareJobs,renderHome,renderRecords,renderAdmin,equipment,awards};})();
